  open();const auto before=rig.source->toPlainText();const int history=rig.source->document()->availableUndoSteps();dialog(false,true);require(!panel->hasChanges()&&rig.source->toPlainText()==before&&rig.source->document()->availableUndoSteps()==history,"MSISE86 Cancel changed parent/source/history");dialog(true,true);require(panel->hasChanges()&&rig.source->toPlainText()==before,"MSISE86 modal bypassed parent Apply");auto *apply=panel->findChild<QDialogButtonBox *>("resourceButtons")->button(QDialogButtonBox::Apply);reveal(apply);apply->click();events();const auto applied=rig.source->toPlainText();require(applied!=before&&applied.endsWith(mission),"MSISE86 Apply changed mission or did not commit");configured(dynamic_cast<ODEModel *>(Moderator::Instance()->GetConfiguredObject("Forces")));rig.closePanels();rig.source->undo();require(rig.source->toPlainText()==before&&rig.window.buildScript(),"MSISE86 Undo failed");rig.source->redo();require(rig.source->toPlainText()==applied&&rig.window.buildScript(),"MSISE86 Redo failed");configured(dynamic_cast<ODEModel *>(Moderator::Instance()->GetConfiguredObject("Forces")));require(rig.window.saveScriptTo(saved)&&rig.window.loadScript(saved)&&rig.window.buildScript()&&rig.source->toPlainText()==applied,"MSISE86 Unicode save/reopen failed");open();dialog(false,false);rig.closePanels();rig.save("final.script",applied.toUtf8());
